ownedComment.body:
«OCL»
{results of soil derived object observations : /*The result of the soil derived object observation shall be of type Number, CharacterString or RangeType.*/
inv: self.soilDerivedObjectObservation.result-&gt;oclIsKindOf(Number) or self.soilDerivedObjectObservation.result-&gt;oclIsKindOf(CharacterString) or self.soilDerivedObjectObservation.result-&gt;oclIsKindOf(RangeType)}

«OCL»
{result of soil site observations : /*The result of the soil site observation shall be of type Number, CharacterString or RangeType.*/
inv: self.soilSiteObservation.result-&gt;oclIsKindOf(Number) or self.soilSiteObservation.result-&gt;oclIsKindOf(CharacterString) or self.soilSiteObservation.result-&gt;oclIsKindOf(RangeType)}

«OCL»
{result of soil profile observations : /*The result of the soil profile observation shall be of type Number, CharacterString or RangeType.*/
inv: self.soilProfileObservation.result-&gt;oclIsKindOf(Number) or self.soilProfileObservation.result-&gt;oclIsKindOf(CharacterString) or self.soilProfileObservation.result-&gt;oclIsKindOf(RangeType)}

«OCL»
{result of profile element observations : /*The result of the profile element observation shall be of type Number, CharacterString or RangeType.*/
inv: self.profileElementObservation.result-&gt;oclIsKindOf(Number) or self.profileElementObservation.result-&gt;oclIsKindOf(CharacterString) or self.profileElementObservation.result-&gt;oclIsKindOf(RangeType)}

«OCL»
{rangeSetValuesConstraint : /*rangeSet values shall be of type Number, CharacterString or RangeType.*/
inv: rangeSet-&gt;oclIsKindOf(Number) or rangeSet-&gt;oclIsKindOf(Characterstring) or rangeSet-&gt;oclIsKindOf(RangeType)}

«OCL»
{rangeSetValuesConstraint : /*rangeSet values shall be of type Number, CharacterString or RangeType.*/
inv: rangeSet-&gt;oclIsKindOf(Number) or rangeSet-&gt;oclIsKindOf(Characterstring) or rangeSet-&gt;oclIsKindOf(RangeType)}

«OCL»
{intervalConstraint : /* at least one of the values shall not be empty*/
inv: self.upperValue-&gt;notEmpty() or self.lowerValue-&gt;notEmpty()}

«OCL»
{code list for soil site observations : /*The observedProperty of the soil site observation shall be specified using a value from the SoilSiteParameterNameValue code list.*/
inv: self.soilSiteParameter.observedProperty-&gt;oclIsKindOf(SoilSiteParameterNameValue)}

«OCL»
{code list for soil profile observations : /*The observedProperty of the soil profile observation shall be specified using a value from the SoilProfileParameterNameValue code list.*/
inv: self.soilProfileParameter.observedProperty-&gt;oclIsKindOf(SoilProfileParameterNameValue)}

«OCL»
{code list for profile element observations : /*The observedProperty of the  profile element observation shall be specified using a value from the ProfileElementParameterNameValue code list.*/
inv: self.profileElementParameter.observedProperty-&gt;oclIsKindOf(ProfileElementParameterNameValue)}

«OCL»
{FoI of soil site observations : /*To fill the featureOfInterest property of the soil site observations of a SoilSite object, that same SoilSite object shall be used.*/
inv: self.soilSiteObservation.featureOfInterest = self}

«OCL»
{FoI of soil profile observations : /*To fill the featureOfInterest property of the soil profile observations of a SoilProfile object, that same SoilProfile object shall be used.*/
inv: self.soilProfileObservation.featureOfInterest = self}

«OCL»
{FoI of profile element observations : /*To fill the featureOfInterest property of the profile element observations of a ProfileElement object, that same ProfileElement object shall be used.*/
inv: self.profileElementObservation.featureOfInterest = self}

«Invariant»
{FoI of Soil derived object observations : /*To fill the featureOfInterest property of the soil derived object observation, the same SoilDerivedObject object shall be used.*/
inv: self.soilDerivedObjectObservation.featureOfInterest = self}

